# owner: platform
import unittest

from hourglass.models import Shift
from hourglass.parsing import parse_span
from hourglass.timesheet import timesheet_lines


def make(worker, day, span):
    return Shift(worker, day, parse_span(span))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_one_decimal(self):
        shifts = [
            make("Ana", "mon", "09:00-10:30"),
            make("Bo", "mon", "09:00-13:00"),
            make("Ana", "tue", "09:00-10:00")
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Bo: 1 shifts, 4.0 hours",
                "Ana: 2 shifts, 2.5 hours"
            ]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        shifts = [make("  ", "mon", "09:00-10:00")]
        with self.assertRaises(ValueError):
            timesheet_lines(shifts)


if __name__ == "__main__":
    unittest.main()
